const L = params.length;
const s = L / 2.2;
const topY = 0.78 * s;
const topW = 0.82 * s;
const plankH = 0.055 * s;
const gap = 0.012 * s;
const plankW = (topW - gap * 4) / 5;
const benchY = 0.44 * s;
const benchW = 0.29 * s;
const benchZ = 0.72 * s;
const frameX = L * 0.34;
const wood = { preset: 'wood', color: params.woodColor, roughness: 0.82 };
const darkWood = { preset: 'wood', color: api.mix(params.woodColor, '#3b2418', 0.34), roughness: 0.88 };
const edgeWood = { preset: 'wood', color: api.mix(params.woodColor, '#d7aa70', 0.18), roughness: 0.78 };
const metal = { preset: 'metal', color: '#34383a', metalness: 0.72, roughness: 0.38 };
for (let i = 0; i < 5; i++) {
  const z = -topW / 2 + plankW / 2 + i * (plankW + gap);
  api.add(api.box(L, plankH, plankW).translate(0, topY, z), i === 0 || i === 4 ? edgeWood : wood);
}
for (let side = -1; side <= 1; side += 2) {
  const z = side * benchZ;
  api.add(api.box(L, plankH, benchW).translate(0, benchY, z), wood);
  api.add(api.box(L + 0.035 * s, 0.035 * s, 0.035 * s).translate(0, benchY + plankH * 0.55, z + side * benchW * 0.35), edgeWood);
}
for (let end = -1; end <= 1; end += 2) {
  const x = end * frameX;
  api.add(api.box(0.105 * s, 0.105 * s, 1.78 * s).translate(x, benchY - 0.075 * s, 0), darkWood);
  for (let side = -1; side <= 1; side += 2) {
    const leg = api.box(0.13 * s, 0.78 * s, 0.13 * s).rotate(side * 24, 0, 0).translate(x, 0.38 * s, side * 0.40 * s);
    api.add(leg, darkWood);
    api.add(api.box(0.16 * s, 0.045 * s, 0.25 * s).translate(x, 0.035 * s, side * 0.67 * s), darkWood);
  }
  api.add(api.box(0.12 * s, 0.10 * s, topW * 0.94).translate(x, topY - 0.09 * s, 0), darkWood);
  for (let side = -1; side <= 1; side += 2) {
    api.add(api.cylinder(0.025 * s, 0.025 * s, 0.018 * s, 10).rotate(90, 0, 0).translate(x, topY + plankH * 0.58, side * topW * 0.31), metal);
    api.add(api.cylinder(0.025 * s, 0.025 * s, 0.018 * s, 10).translate(x, benchY + plankH * 0.58, side * benchZ), metal);
  }
}
api.add(api.box(L * 0.74, 0.10 * s, 0.10 * s).translate(0, 0.36 * s, 0), darkWood);
for (let side = -1; side <= 1; side += 2) {
  for (let end = -1; end <= 1; end += 2) {
    const path = [[end * frameX, 0.34 * s, side * 0.04 * s], [end * L * 0.12, 0.70 * s, side * 0.30 * s]];
    api.add(api.tube(path, 0.035 * s, 6), darkWood);
  }
}
api.collider({ kind: 'box', halfExtents: [L / 2, plankH / 2, topW / 2], offset: [0, topY, 0] });
for (let side = -1; side <= 1; side += 2) {
  api.collider({ kind: 'box', halfExtents: [L / 2, plankH / 2, benchW / 2], offset: [0, benchY, side * benchZ] });
}
for (let end = -1; end <= 1; end += 2) {
  for (let side = -1; side <= 1; side += 2) {
    api.collider({ kind: 'box', halfExtents: [0.065 * s, 0.39 * s, 0.065 * s], offset: [end * frameX, 0.38 * s, side * 0.40 * s], rotation: [side * 24, 0, 0] });
  }
}
return api.build();
